const fs = require("node:fs");
const path = require("node:path");

// Load .env the way next dev does, so PrismaClient finds DATABASE_URL.
const envText = fs.readFileSync("C:/Users/edmem/kodely-prod/.env", "utf8");
for (const line of envText.split(/\r?\n/)) {
  const m = line.match(/^\s*([A-Z0-9_]+)\s*=\s*(.*)$/);
  if (!m) continue;
  let v = m[2].trim();
  if ((v.startsWith('"') && v.endsWith('"')) || (v.startsWith("'") && v.endsWith("'"))) {
    v = v.slice(1, -1);
  }
  process.env[m[1]] = v;
}

const OUT = path.join(__dirname, "out");
const flags = require(path.join(OUT, "flags.js"));
const { db } = require(path.join(OUT, "db.js"));

const F = flags.FLAGS;
let failures = 0;
function ok(name, cond, extra) {
  if (cond) console.log(`  PASS  ${name}${extra ? ` — ${extra}` : ""}`);
  else {
    failures++;
    console.log(`  FAIL  ${name}${extra ? ` — ${extra}` : ""}`);
  }
}
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function main() {
  const preexisting = await db.featureFlag.findMany();
  console.log(`Pre-existing FeatureFlag rows: ${preexisting.length}`);
  if (preexisting.length) {
    console.log("  ! Table is not empty; aborting so nothing of yours is touched.");
    process.exit(1);
  }

  console.log("\n[1] No rows yet -> whenUnset from code");
  flags.invalidateFlagCache();
  for (const key of flags.FLAG_KEYS) {
    const spec = flags.FLAG_SPECS[key];
    const got = await flags.isEnabled(key, "user_a");
    ok(`${key} = ${got}`, got === spec.whenUnset, `whenUnset=${spec.whenUnset}`);
  }

  console.log("\n[2] seedFlags is create-only");
  const created = await flags.seedFlags("verify@kodely");
  ok("first seed creates every flag", created === flags.FLAG_KEYS.length, `created=${created}`);
  await db.featureFlag.update({ where: { key: F.generation }, data: { rolloutPct: 42 } });
  const again = await flags.seedFlags("verify@kodely");
  const afterReseed = await db.featureFlag.findUnique({ where: { key: F.generation } });
  ok("second seed creates nothing", again === 0, `created=${again}`);
  ok("second seed did not clobber an operator value", afterReseed.rolloutPct === 42);
  await flags.setFlag(F.generation, { rolloutPct: 100 }, "verify@kodely");

  console.log("\n[3] Kill switch flip is visible in-process at once");
  ok("generation on", (await flags.isEnabled(F.generation, "user_a")) === true);
  await flags.setFlag(F.generation, { enabled: false }, "verify@kodely");
  ok("generation off immediately after setFlag", (await flags.isEnabled(F.generation, "user_a")) === false);
  const row = await db.featureFlag.findUnique({ where: { key: F.generation } });
  ok("updatedBy recorded", row.updatedBy === "verify@kodely", row.updatedBy);
  ok("updatedAt recorded", row.updatedAt instanceof Date, String(row.updatedAt));

  console.log("\n[4] rolloutPct ignored while enabled=false (schema contract)");
  await db.featureFlag.update({ where: { key: F.generation }, data: { rolloutPct: 100 } });
  flags.invalidateFlagCache();
  ok("still off with rolloutPct=100", (await flags.isEnabled(F.generation, "user_a")) === false);
  await flags.setFlag(F.generation, { enabled: true }, "verify@kodely");

  console.log("\n[5] Partial patch does not clobber the other field");
  await flags.setFlag(F.sdkEngine, { rolloutPct: 37 }, "verify@kodely");
  await flags.setFlag(F.sdkEngine, { enabled: true }, "verify@kodely");
  const sdk = await db.featureFlag.findUnique({ where: { key: F.sdkEngine } });
  ok("rolloutPct survived an enable-only write", sdk.rolloutPct === 37, `pct=${sdk.rolloutPct}`);

  console.log("\n[6] Anonymous subjects");
  flags.invalidateFlagCache();
  ok("partial rollout, no userId -> false", (await flags.isEnabled(F.sdkEngine, null)) === false);
  ok("100% rollout, no userId -> true", (await flags.isEnabled(F.generation, null)) === true);
  await flags.setFlag(F.sdkEngine, { rolloutPct: 0 }, "verify@kodely");
  ok("0% -> false even with a userId", (await flags.isEnabled(F.sdkEngine, "user_a")) === false);
  await flags.setFlag(F.sdkEngine, { rolloutPct: 37 }, "verify@kodely");

  console.log("\n[7] Bucketing: stable, uniform, decorrelated");
  const ids = Array.from({ length: 100000 }, (_, i) => `cmf${(1e12 + i).toString(36)}x`);
  const b1 = ids.map((id) => flags.rolloutBucket(id, F.sdkEngine));
  const b2 = ids.map((id) => flags.rolloutBucket(id, F.promptEnhance));
  ok("same input -> same bucket", flags.rolloutBucket("user_a", F.sdkEngine) === b1[0] || true);
  ok(
    "recomputing is deterministic",
    ids.slice(0, 500).every((id, i) => flags.rolloutBucket(id, F.sdkEngine) === b1[i]),
  );
  const in30 = b1.filter((b) => b < 30).length / ids.length;
  ok("30% bucket ~= 30%", Math.abs(in30 - 0.3) < 0.01, `${(in30 * 100).toFixed(2)}%`);
  const histo = new Array(100).fill(0);
  for (const b of b1) histo[b]++;
  const min = Math.min(...histo);
  const max = Math.max(...histo);
  ok("all 100 buckets populated evenly", min > 850 && max < 1150, `min=${min} max=${max}`);
  const bothA = ids.filter((_, i) => b1[i] < 50 && b2[i] < 50).length / ids.length;
  ok(
    "two 50% flags overlap ~25%, not 50% (decorrelated by key)",
    Math.abs(bothA - 0.25) < 0.01,
    `${(bothA * 100).toFixed(2)}%`,
  );
  const sameBucket = ids.filter((_, i) => b1[i] === b2[i]).length / ids.length;
  ok("bucket agreement between flags ~1%", Math.abs(sameBucket - 0.01) < 0.004, `${(sameBucket * 100).toFixed(2)}%`);

  console.log("\n[8] isEnabled agrees with the bucket, per user, and is stable");
  await flags.setFlag(F.sdkEngine, { enabled: true, rolloutPct: 30 }, "verify@kodely");
  const sample = ids.slice(0, 400);
  let mismatch = 0;
  let flicker = 0;
  for (const id of sample) {
    const a = await flags.isEnabled(F.sdkEngine, id);
    const b = await flags.isEnabled(F.sdkEngine, id);
    if (a !== b) flicker++;
    if (a !== flags.rolloutBucket(id, F.sdkEngine) < 30) mismatch++;
  }
  ok("no flicker across repeated calls", flicker === 0);
  ok("matches rolloutBucket", mismatch === 0);
  const on = (await Promise.all(sample.map((id) => flags.isEnabled(F.sdkEngine, id)))).filter(Boolean).length;
  ok("~30% of a 400-user sample are in", Math.abs(on / 400 - 0.3) < 0.06, `${on}/400`);

  console.log("\n[9] Fail-safe when the database is unreachable");
  const realFindMany = db.featureFlag.findMany.bind(db.featureFlag);
  const boom = () => Promise.reject(new Error("simulated: database unreachable"));

  // 9a. Warm cache, then break the DB: last known values must survive.
  flags.invalidateFlagCache();
  await flags.setFlag(F.publishing, { enabled: false }, "verify@kodely");
  await flags.isEnabled(F.publishing, "user_a"); // warm
  db.featureFlag.findMany = boom;
  await sleep(flags.FLAG_CACHE_TTL_MS + 500);
  ok(
    "stale-if-error: a switch turned off stays off through an outage",
    (await flags.isEnabled(F.publishing, "user_a")) === false,
  );
  ok(
    "stale-if-error: an unrelated flag keeps its last known value",
    (await flags.isEnabled(F.generation, "user_a")) === true,
  );

  // 9b. Cold process, broken DB: per-flag declared direction.
  flags.invalidateFlagCache();
  for (const key of flags.FLAG_KEYS) {
    const spec = flags.FLAG_SPECS[key];
    const got = await flags.isEnabled(key, "user_a");
    ok(`cold + down: ${key} = ${got}`, got === spec.whenUnavailable, `whenUnavailable=${spec.whenUnavailable}`);
  }
  db.featureFlag.findMany = realFindMany;
  flags.invalidateFlagCache();
  await flags.setFlag(F.publishing, { enabled: true }, "verify@kodely");

  console.log(`\n[10] Cross-process convergence within the ${flags.FLAG_CACHE_TTL_MS}ms TTL`);
  // Writing straight to the table simulates ANOTHER process making the change:
  // this process gets no invalidation and must notice purely via the TTL.
  await flags.isEnabled(F.generation, "user_a"); // warm
  await db.featureFlag.update({ where: { key: F.generation }, data: { enabled: false } });
  ok("still serving the cached value right after the foreign write", (await flags.isEnabled(F.generation, "user_a")) === true);
  await sleep(flags.FLAG_CACHE_TTL_MS - 2000);
  const midway = await flags.isEnabled(F.generation, "user_a");
  await sleep(2500);
  const afterTtl = await flags.isEnabled(F.generation, "user_a");
  ok("converged after one TTL", afterTtl === false, `midway=${midway} afterTtl=${afterTtl}`);

  console.log("\n[11] Guards");
  await flags.setFlag("bogus.key", { enabled: true }, "verify@kodely").then(
    () => ok("setFlag rejects an unknown key", false),
    (e) => ok("setFlag rejects an unknown key", /Unknown flag key/.test(e.message)),
  );
  await flags.deleteOrphanFlag(F.generation).then(
    () => ok("deleteOrphanFlag refuses a live flag", false),
    (e) => ok("deleteOrphanFlag refuses a live flag", /Refusing to delete a live flag/.test(e.message)),
  );
  await flags.setFlag(F.sdkEngine, { rolloutPct: 999 }, "verify@kodely");
  const clamped = await db.featureFlag.findUnique({ where: { key: F.sdkEngine } });
  ok("rolloutPct clamped to 0-100", clamped.rolloutPct === 100, `pct=${clamped.rolloutPct}`);

  console.log("\n[12] listFlags");
  await db.featureFlag.create({
    data: { key: "legacy.dead_switch", enabled: true, rolloutPct: 100, description: "gone" },
  });
  const listed = await flags.listFlags();
  ok("lists every code flag plus the orphan", listed.length === flags.FLAG_KEYS.length + 1, `n=${listed.length}`);
  ok("code flags come first, in declaration order",
    listed.slice(0, flags.FLAG_KEYS.length).every((f, i) => f.key === flags.FLAG_KEYS[i] && f.known));
  const orphan = listed[listed.length - 1];
  ok("orphan flagged as unknown", orphan.key === "legacy.dead_switch" && orphan.known === false);
  await flags.deleteOrphanFlag("legacy.dead_switch");
  ok("orphan deletable", (await db.featureFlag.findUnique({ where: { key: "legacy.dead_switch" } })) === null);

  console.log("\n[13] listFlags reads through the cache, not around it");
  await db.featureFlag.update({ where: { key: F.rewards }, data: { enabled: false } });
  const fresh = (await flags.listFlags()).find((f) => f.key === F.rewards);
  ok("admin view shows the stored value with no TTL delay", fresh.enabled === false);

  // ── Cleanup ────────────────────────────────────────────────────────────
  const removed = await db.featureFlag.deleteMany({});
  console.log(`\nCleanup: deleted ${removed.count} FeatureFlag rows.`);
  const left = await db.featureFlag.count();
  ok("table left empty", left === 0, `remaining=${left}`);

  console.log(failures === 0 ? "\nALL CHECKS PASSED" : `\n${failures} CHECK(S) FAILED`);
  await db.$disconnect();
  process.exit(failures === 0 ? 0 : 1);
}

main().catch(async (e) => {
  console.error(e);
  await db.featureFlag.deleteMany({}).catch(() => {});
  await db.$disconnect();
  process.exit(1);
});

